// levels/07.js: level 7, `memory` (task F17). The explorer's own map of the demo store, as the explorer drew it.
//
// What is on the screen. Four real frames of the plugin's explorer (frames/07-memory-x01 x02 x04 x08.png, task F05): the Force
// map of the 18 sessions of the demo profile at four zoom steps. At the full view the film shows x01 pixel for pixel (1 px of the
// frame = 1/S of a world unit, the frame's centre is the origin). The camera pulls back from the box of the dogfood chat to the
// whole map, and the frame that fits the zoom is laid over the others, so the text of the boxes is never a stretched bitmap.
// The film draws no text of its own here: the words are the explorer's, and the caption and the count are the engine's.
//   - The map area only: the explorer's toolbar (above) and status bar (below) are cut, because the film's count and caption go there.
//   - The dogfood chat (root 3f77b3b8, the session that level 5 replays) is the one small box that holds the level below. In the
//     three zoomed frames the rows of text inside THAT box are cleared (its frame, header and title stay); nothing else of any
//     frame is changed. The level below (rcpt, which holds the window of level 5) is drawn there by the engine through place().
//   - No colour, glow or mark is added. (The explorer's heat of every session is 0 in the dump, so no heat is drawn.)
//   - place() turns the level below by 0 rad: the explorer's frames stay upright through the flight.
// For the join (F30/F31): BELOW_R is the radius R of the level below. kit.center(k) gives only its centre, so the value is copied from
// levels/06.js (R 1.7, cx -0.08, cy -0.02); change it if that file changes. FIT is the part of the box's half width that its disc fills.
// One fact for the join: levels/06.js draws the receipt chain of session local-4025dc8d (the map's node de23b06f, "hive put"),
// and level 5 replays the dogfood chat 3f77b3b8. They are two sessions. This level puts level 6 in the box of the dogfood chat,
// because the plan says that the window of level 5 is the one small box of the map and F05 made its frames around that box. The
// frames hold no zoom into the box of de23b06f: to put level 6 there, F05's capture has to be made again around that box.
//
// The data (the four frames as lossless images, the box of each, the count) is the function data() at the end of this file. It is
// written by 07.build.py from frames/, store.json and folds.json; the code above it is by hand.
(function (F) {
  'use strict';
  const { C, S, clamp, seg, at, center } = F.kit;
  const D = data();
  const W = 1920, CROP_Y = D.crop.y, CROP_H = D.crop.h;
  const BELOW_R = 1.7, FIT = 0.8;
  // the zoom z = pixels on the screen for one pixel of the x01 frame. A frame lies over the one before it as z passes [lo, hi],
  // close to its own zoom (a frame of step s fills the screen at z = s; below that it is smaller than the screen and the
  // blurrier frame under it shows around it). The dissolve is short: the explorer's labels keep their size at every zoom, so two
  // frames never agree on them and a long dissolve shows both. All of the map fades in as the camera pulls back through
  // [ZIN0, ZIN1], so the flight starts on the level below alone, on black.
  const RAMP = [[0, 0], [1.5, 1.95], [3.0, 3.9], [6.0, 7.8]], ZIN0 = 9, ZIN1 = 18;

  // The dogfood box in the x01 frame, as a point and a width of the level's own world.
  const b1 = D.frames[0].box, BC = [(b1[0] + b1[2] / 2 - W / 2) / S, (b1[1] + b1[3] / 2 - 540) / S], BW = b1[2] / S;
  // Each frame as a rectangle of the world: the same box centre in every frame, so the frames lie on one another.
  const FR = D.frames.map((f, i) => {
    const [bx, by, bw, bh] = f.box, cx = bx + bw / 2, cy = by + bh / 2, s = f.s;
    return {
      s, img: new Image(), cv: null, feather: i === 0 ? [0, 16] : [48, 48], lo: RAMP[i][0], hi: RAMP[i][1],
      x: BC[0] + (0 - cx) / S / s, y: BC[1] + (CROP_Y - cy) / S / s, w: W / S / s, h: CROP_H / S / s,
    };
  });

  // A frame with its edges faded, so that the sharper frame over the blurrier one has no hard border.
  function faded(img, fx, fy) {
    const cv = document.createElement('canvas'); cv.width = img.naturalWidth; cv.height = img.naturalHeight;
    const c = cv.getContext('2d'); c.drawImage(img, 0, 0); c.globalCompositeOperation = 'destination-in';
    const ramp = (x1, y1, x2, y2, n, len) => {
      const g = c.createLinearGradient(x1, y1, x2, y2);
      g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(n / len, '#000'); g.addColorStop(1 - n / len, '#000'); g.addColorStop(1, 'rgba(0,0,0,0)');
      c.fillStyle = g; c.fillRect(0, 0, cv.width, cv.height);
    };
    if (fx) ramp(0, 0, cv.width, 0, fx, cv.width);
    if (fy) ramp(0, 0, 0, cv.height, fy, cv.height);
    return cv;
  }
  // The images decode after the script has run. The page's `ready` waits for them, so no frame of a render is painted before.
  const decoded = Promise.all(FR.map((f, i) => {
    f.img.src = `data:${D.frames[i].mime};base64,${D.frames[i].b64}`;
    return f.img.decode().then(() => { f.cv = faded(f.img, f.feather[0], f.feather[1]); });
  }));
  if (window.ready && typeof window.ready.then === 'function') window.ready = Promise.all([window.ready, decoded]).then(r => r[0]);
  else decoded.catch(e => console.error('levels/07.js: ' + e));

  // Paint the map at zoom z; `small` is the miniature that stands for the level when it is tiny (x01 only).
  // F31: while the map fades in (fade < 1) its frames are put together at full strength on a canvas of their own, and that canvas is laid
  // over the film once, at the fade. Before, each frame was drawn at the fade, so the four added up (about 4 times the fade when it is small):
  // the map came in faster than the fade says, and the first frame of it was a step of 7 levels of grey over the whole screen (the 8-bit
  // rounding of four draws at alpha 0.02), which qa.py scored as a pop at 51.30 s. Where the fade is 1 (the hold, the frames of a level above)
  // the frames are drawn straight on the film, as before.
  let GROUP = null;
  function paint(g, z, small) {
    const ctx = g.ctx, A = small ? 0.9 : 1 - seg(z, ZIN0, ZIN1), fade = A * g.a;
    if (fade <= 0.004) return;
    // Something is to be drawn, so the images must be there: a frame with no map would be wrong and silent. Fail loudly instead.
    if (!FR[0].cv) throw new Error('levels/07.js: the images of the map are not decoded yet (window.ready was read before this file ran)');
    let to = ctx;
    if (!small && fade < 0.999) {
      const cv = ctx.canvas;
      if (!GROUP || GROUP.width !== cv.width || GROUP.height !== cv.height) { GROUP = document.createElement('canvas'); GROUP.width = cv.width; GROUP.height = cv.height; }
      to = GROUP.getContext('2d'); to.setTransform(1, 0, 0, 1, 0, 0); to.globalAlpha = 1; to.clearRect(0, 0, cv.width, cv.height);
      const M = g.M; to.setTransform(M[0], M[1], M[2], M[3], M[4], M[5]);
    } else g.set();
    to.imageSmoothingEnabled = true; to.imageSmoothingQuality = 'high';
    for (let i = 0; i < FR.length; i++) {
      const f = FR[i]; if (!f.cv || (small && i)) continue;
      const a = i ? seg(z, f.lo, f.hi) : 1; if (a <= 0.004) continue;
      to.globalAlpha = to === ctx ? clamp(a * fade) : a;
      to.drawImage(f.cv, f.x, f.y, f.w, f.h);
    }
    if (to !== ctx) { ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.globalAlpha = clamp(fade); ctx.drawImage(GROUP, 0, 0); }
    ctx.globalAlpha = 1;
  }

  const me = F.def({
    name: 'memory', color: C.GOLD, R: 2.05, cx: 0, cy: 0,
    zoom: 2.8, dwell: 4.0, lines: D.lines,
    hint: ['BM25 + neighbors', 1.9],
    // the level below, turned by 0, with its disc in the dogfood box (a little below the middle: the box has a header row)
    place: () => at(BC[0], BC[1] + 0.02 * BW, FIT * BW / 2 / BELOW_R, 0, center(me.k - 1)),
    draw(g) { paint(g, g.s / S, false); },
    tiny(g) { paint(g, 0, true); },
    // the climb out to the map is a flute line that rises (a lone last note rings 1.8 s); the caption is written in on a wood block
    ev: [[-1.2, 'flute', 3, 0.3, -0.2], [-0.3, 'flute', 5, 0.32, 0], [0.6, 'flute', 7, 0.3, 0.2], [1.9, 'wood', 4, 0.3, 0.1]],
  });

  //#data-begin
  function data() {
    return {
      // levels['7'].lines of store.json = the lines of the 18 sessions of the map
      lines: 20434, root: '3f77b3b8', crop: { y: 72, h: 984 },
      // s = zoom step of the explorer frame; box = the dogfood box in that frame, in px of the whole 1920x1080 frame
      frames: [
        // 07-memory-x01.png  sha256 cd1b22664e34c389c1340328326b08510ddc7471dbe462eb09e79ba6b673e21b
        { s: 1, box: [539.7, 469.9, 89.6, 89.6], mime: 'image/webp', b64: '' },
        // 07-memory-x02.png  sha256 6cd059c0c9414d57c62d10b55e86000ffbb8b57ec8593e41047eb70258243010
        { s: 2, box: [620, 441.6, 179.2, 179.2], mime: 'image/webp', b64: '' },
        // 07-memory-x04.png  sha256 82d4603f945ccb6de718f943c5ffb5aa2da9b1319a5fc318ac6a8310116d711c
        { s: 4, box: [655.6, 368.4, 358.4, 358.4], mime: 'image/webp', b64: '' },
        // 07-memory-x08.png  sha256 d328d61ccc66bc6cd735cce8674e7cf67db5256054b9b158b160f9382fd43d84
        { s: 8, box: [601.6, 205.6, 716.7, 716.7], mime: 'image/webp', b64: '' },
      ],
    };
  }
  //#data-end
})(Film);
